<?php require_once __DIR__.'/config/db.php';if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$email=trim($_POST['email']??'');if(filter_var($email,FILTER_VALIDATE_EMAIL)){try{$pdo->prepare('INSERT INTO newsletter_subscribers(email) VALUES(?)')->execute([$email]);flash('success','You are subscribed.');}catch(PDOException $e){flash('success','You are already subscribed.');}}else flash('error','Enter a valid email.');redirect('index.php');}redirect('index.php');
